insert into public.pages (path, title, status, content) values ($twcseed231$/about$twcseed231$, $twcseed232$About$twcseed232$, 'published', $twcseed233${"headline":"We build bold brands with clarity, creativity, and cultural insight.","philosophy_heading":"Our Philosophy","philosophy":"Tipple Works Co. is a creative-led marketing agency built for ambitious brands. We’re passionate about storytelling, strategy, and design that doesn’t just look good—but delivers real results.","how_heading":"How We Work","how":"From strategy and identity to campaigns and content—we believe in sharp thinking, clean execution, and working as an extension of your team to bring your brand to life.","cta_heading":"Let’s build something unforgettable.","cta_body":"Start your next project with Tipple Works Co. today.","cta_label":"Get in Touch","join_heading":"Join Our Team","join_body":"We’re always looking for talented, curious, and driven people to grow with us.","join_label":"Join Us"}$twcseed233$::jsonb) on conflict (path) do nothing;
