insert into public.pages (path, title, status, content) values ($twcseed243$/privacy-policy$twcseed243$, $twcseed244$Privacy Policy$twcseed244$, 'published', $twcseed245${"heading":"Privacy Policy","effective":"Effective Date: June 2025","intro":"Tipple Works Co. (“we”, “us”, or “our”) values your privacy. This Privacy Policy outlines how we collect, use, and protect your personal information when you interact with our website or services.","items":["What we collect: Contact details, browsing behavior, and submitted inquiries.","How we use it: To respond to you, improve services, and provide relevant communication.","Data Sharing: Only with trusted tools used to run our business (analytics, forms).","Security: Your data is stored securely and used responsibly.","Your Rights: You may request access or deletion of your personal info at any time."],"closing":"For any queries, contact us at"}$twcseed245$::jsonb) on conflict (path) do nothing;
insert into public.pages (path, title, status, content) values ($twcseed246$/terms-of-service$twcseed246$, $twcseed247$Terms of Service$twcseed247$, 'published', $twcseed248${"heading":"Terms of Service","effective":"Effective Date: June 2025","intro":"By using our website or services, you agree to the following terms:","items":["Content and visuals on this site are the property of Tipple Works Private Limited.","Service engagements are governed by mutual agreements or project scopes.","We are not liable for external links or third-party actions.","We may change or update these terms at our discretion."],"closing":"For any concerns, reach out to"}$twcseed248$::jsonb) on conflict (path) do nothing;
